const fs=require('fs');
const dir='D:/备份文件夹/探域问答审核-20260905';
const cards=JSON.parse(fs.readFileSync(dir+'/confirmation-6789-candidates.json','utf8'));
const plan=new Map();
const body=c=>c.content.map(x=>x.content).join('\n');
function set(i,answer){const c=cards[i];const old=body(c);const q=old.split('\nA:')[0];plan.set(c.id,{id:c.id,type:c.type,includeCondition:c.includeCondition,before:old,after:q+'\nA:'+answer});}
const gift='本店C1型号不参加额外赠品活动，其他型号支持参加；标配配件与活动赠品分开核对。';
const invoice='本店在线销售的主机类商品支持电子普通发票，不提供收据。确认收货、平台打款后，由财务统一批量开票，预计7个工作日左右完成。个人请提供姓名，公司请提供公司抬头和税号；本店国补订单仅开个人发票。请核对开票金额，并提供开票资料及接收邮箱；内容和金额按实际交易开具。';
for(const i of [18,58])set(i,'个人电子普通发票请提供您确认的姓名及接收邮箱，不默认使用收货人姓名。'+invoice);
for(const i of [19,20,31,56])set(i,'请提供订单号，由人工查询登记及开票进度；提交资料不代表已登记或已开具，也不代表已加急。'+invoice);
for(const i of [21,22,33,34])set(i,'目前已确认的常规开票方式为电子普通发票。如需专票，请先由财务确认是否支持和必要资料，不预先要求盖章授权。'+invoice);
set(32,'亲亲，本店提供电子普通发票，不提供收据。'+invoice);
set(41,'较早订单能否补开发票，需提供订单号由财务核实，不预先保证或拒绝。'+invoice);
set(57,'本店提供电子普通发票，收到后可自行打印。'+invoice+'本店网购售后可凭订单号查询购物记录和质保时间，无需为申请售后另行提供发票。');
for(const i of [5,61,62,63,64,66])set(i,'本店不提供上门维修。您可提供型号、订单号及故障现象，由售后远程协助排查；需要维修时寄回厂家。寄送地址、维修方案和具体费用由人工核实，不代约当地上门师傅。');
set(10,'维修换下的旧零部件由厂家统一回收，不返还客户。具体更换项目请提供维修单号，由人工核对维修记录；未核实记录前不声称已经更换或更换为全新件。');
set(11,'非本店购买的设备可提供型号、购机凭证、说明书或机器标注的生产日期及故障说明，由人工核实维修资格和保修起算依据。非本店购买的维修运费由客户承担，具体金额由人工确认。');
set(40,'亲亲，'+gift+'非C1制氧机可参与晒单送氧气袋活动，请提供型号或订单核对领取安排。');
for(const i of [15,24,28,52])set(i,gift+'请提供订单号及相关活动记录，由人工查询赠品登记和发货进度；未查询前不确认已登记、已寄出或已经补发。');
for(const i of [23,45,49,50,53,55])set(i,gift+'如需赠品与主机同步发出，请提供订单号由人工核对安排；是否分包、发货仓库及时间以实际记录为准，不预先承诺已安排。');
for(const i of [27,47,48])set(i,gift+'氧气袋、血氧仪等具体领取组合请提供型号或订单，由人工核对对应活动安排；不代表所有赠品都自动随主机发出。');
set(26,gift+'参加晒单活动时请如实分享使用体验，不要求好评或修改评价。请提供订单号及晒单凭证，由人工核对领取安排；收件资料仅在订单信息无法满足寄送需要时补充，不预先承诺已经登记或寄出。');
set(51,gift+'参与晒单活动不限制评价好坏，请真实评价，不以修改或删除差评换取赠品。具体领取及发货安排由人工核对。');
for(const i of [25,44])set(i,gift+'不想晒单或遇到使用问题可直接说明，由人工核对领取安排或处理问题；不要求修改、删除评价，不在未查询前说已经登记补发。');
set(43,gift+'活动赠品与购买套餐内的标配配件不同。参加晒单请真实分享体验，不要求好评；具体领取安排由人工核对。');
set(54,gift+'请提供型号、订单号及实际收到的物品，由人工逐项核对标配配件和活动赠品，不凭未收到就推断超过前100名，也不在未查记录前声称已经发齐。');
set(9,'C1型号不参加额外赠品活动。若使用时感觉干燥，请说明型号及使用情况，由售后核对适配配件和处理方式，不自行加装湿化组件；质量问题按售后流程处理，不以放弃退货为前提。');
const c=cards[83];plan.set(c.id,{id:c.id,type:c.type,includeCondition:c.includeCondition,before:body(c),after:body(c).replace('- 赠品：送吸氧大礼包（内含吸氧管、过滤器、电源线、过滤棉、说明书）','- 活动规则：C1型号不参加额外赠品活动。随购套餐的标配配件请按实际订单清单核对，不将标配与活动赠品混为一谈。')});
fs.writeFileSync(dir+'/confirmation-6789-plan.json',JSON.stringify([...plan.values()],null,2));
console.log(JSON.stringify({planned:plan.size}));
